	SourceRef: {
		tag: "SourceRef",
		namespace: {
			prefix: "eIEC61850-6-100",
			uri: "http://www.iec.ch/61850/2019/SCL/6-100"
		},
		documentation: "Reference to a data in the process",
		parents: ["LNodeInputs"],
		attributes: {
			sequence: [
				"desc",
				"extRefAddr",
				"extRefUuid",
				"input",
				"inputInst",
				"originUuid",
				"pDA",
				"pDO",
				"pLN",
				"resourceName",
				"resourceUuid",
				"service",
				"source",
				"sourceDaName",
				"sourceDoName",
				"sourceLNodeUuid",
				"templateUuid",
				"uuid"
			],
			details: {
				desc: {
					default: "",
					facets: { whiteSpace: "replace" }
				},
				extRefAddr: { facets: { whiteSpace: "replace" } },
				extRefUuid: { facets: {
					pattern: ["[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"],
					whiteSpace: "preserve"
				} },
				input: {
					required: !0,
					facets: {
						minLength: 1,
						whiteSpace: "replace"
					}
				},
				inputInst: {
					default: "1",
					facets: {
						minInclusive: 1,
						whiteSpace: "collapse"
					}
				},
				originUuid: { facets: {
					pattern: ["[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"],
					whiteSpace: "preserve"
				} },
				pDA: { facets: { whiteSpace: "replace" } },
				pDO: { facets: { whiteSpace: "replace" } },
				pLN: { facets: { whiteSpace: "replace" } },
				resourceName: { facets: { whiteSpace: "replace" } },
				resourceUuid: { facets: {
					pattern: ["[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"],
					whiteSpace: "preserve"
				} },
				service: { facets: {
					enumeration: [
						"Poll",
						"Report",
						"GOOSE",
						"SMV",
						"Wired",
						"Internal"
					],
					pattern: ["[A-Za-z_:][-.:0-9A-Z_a-z]*"],
					whiteSpace: "collapse"
				} },
				source: { facets: {
					pattern: [".+(/.+)*"],
					whiteSpace: "replace"
				} },
				sourceDaName: { facets: {
					pattern: ["[a-zA-Z][a-zA-Z0-9]*(\\([0-9]+\\))?(\\.[a-zA-Z][a-zA-Z0-9]*(\\([0-9]+\\))?)*"],
					whiteSpace: "replace"
				} },
				sourceDoName: { facets: {
					pattern: ["[A-Z][0-9A-Za-z]{0,11}(\\.[a-z][0-9A-Za-z]*(\\([0-9]+\\))?)?"],
					whiteSpace: "replace"
				} },
				sourceLNodeUuid: { facets: {
					pattern: ["[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"],
					whiteSpace: "preserve"
				} },
				templateUuid: { facets: {
					pattern: ["[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"],
					whiteSpace: "preserve"
				} },
				uuid: { facets: {
					pattern: ["[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"],
					whiteSpace: "preserve"
				} }
			},
			identityFields: [
				"input",
				"inputInst",
				"pDA"
			]
		},
		children: {
			sequence: [
				"Text",
				"GooseParametersRef",
				"SMVParametersRef",
				"ReportParametersRef",
				"BinaryWiringParametersRef",
				"AnalogueWiringParametersRef"
			],
			any: !0,
			details: {
				Text: {
					maxOccurs: 1,
					namespace: {
						prefix: "eIEC61850-6-100",
						uri: "http://www.iec.ch/61850/2019/SCL/6-100"
					}
				},
				GooseParametersRef: {
					required: !0,
					minOccurs: 1,
					maxOccurs: 1
				},
				SMVParametersRef: {
					required: !0,
					minOccurs: 1,
					maxOccurs: 1
				},
				ReportParametersRef: {
					required: !0,
					minOccurs: 1,
					maxOccurs: 1
				},
				BinaryWiringParametersRef: {
					required: !0,
					minOccurs: 1,
					maxOccurs: 1
				},
				AnalogueWiringParametersRef: {
					required: !0,
					minOccurs: 1,
					maxOccurs: 1
				}
			},
			choices: [{
				options: [
					"AnalogueWiringParametersRef",
					"BinaryWiringParametersRef",
					"GooseParametersRef",
					"ReportParametersRef",
					"SMVParametersRef"
				],
				maxOccurs: 1
			}]
		}
	},
